MN restaurant_cash DECIMAL(14,2) NOT NULL DEFAULT 0.00 AFTER cash_amount");if(!db()->query("SHOW COLUMNS FROM management_bank_deposit_records LIKE 'upload_group'")->fetchColumn())db()->exec("ALTER TABLE management_bank_deposit_records ADD COLUMN upload_group VARCHAR(64) NOT NULL DEFAULT '' AFTER refunds_description");if(!db()->query("SHOW COLUMNS FROM management_bank_deposit_records LIKE 'status'")->fetchColumn())db()->exec("ALTER TABLE management_bank_deposit_records ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'submitted' AFTER upload_group");if(!db()->query("SHOW COLUMNS FROM management_bank_deposit_records LIKE 'finalized_by_admin_user_id'")->fetchColumn())db()->exec("ALTER TABLE management_bank_deposit_records ADD COLUMN finalized_by_admin_user_id BIGINT UNSIGNED NULL AFTER status");if(!db()->query("SHOW COLUMNS FROM management_bank_deposit_records LIKE 'finalized_at'")->fetchColumn())db()->exec("ALTER TABLE management_bank_deposit_records ADD COLUMN finalized_at DATETIME NULL AFTER finalized_by_admin_user_id");db()->exec("UPDATE management_bank_deposit_records SET upload_group=CONCAT('record-',id) WHERE upload_group=''");db()->exec("CREATE TABLE IF NOT EXISTS management_bank_deposit_files (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,management_property_id BIGINT UNSIGNED NOT NULL,upload_group VARCHAR(64) NOT NULL,file_path VARCHAR(500) NOT NULL,original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(150) NOT NULL,file_size BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_management_bank_deposit_files_group(management_property_id,upload_group)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$message='Bank Deposits, Restaurant Cash, and finalization controls are installed.';}catch(Throwable $exception){$error=$exception->getMessage();error_log('Bank Deposits upgrade failed: '.$exception->getMessage());}}
